package tv.plus.pro.unified;
import android.app.*;import android.os.*;import android.graphics.*;import android.view.*;import android.widget.*;import java.io.*;import java.net.*;
/** Minimal localhost RFB 3.8 viewer: no authentication, raw encoding, 32-bit true color. */
public class VncActivity extends Activity {
 volatile boolean active=true; Socket socket; DataInputStream in; DataOutputStream out; Frame view; int width,height; int[] pixels; final Object writeLock=new Object();
 @Override public void onCreate(Bundle b){super.onCreate(b);getWindow().getDecorView().setSystemUiVisibility(5894|1024|512);view=new Frame();setContentView(view);new Thread(this::connect).start();}
 void connect(){try{socket=new Socket();socket.connect(new InetSocketAddress("127.0.0.1",5901),5000);socket.setTcpNoDelay(true);in=new DataInputStream(new BufferedInputStream(socket.getInputStream()));out=new DataOutputStream(new BufferedOutputStream(socket.getOutputStream()));
 byte[] ver=new byte[12];in.readFully(ver);String version=new String(ver,"US-ASCII");if(!version.startsWith("RFB 003."))throw new IOException("RFB sürümü desteklenmiyor");out.write("RFB 003.008\n".getBytes("US-ASCII"));out.flush();int count=in.readUnsignedByte();if(count==0){int len=in.readInt();throw new IOException(readString(len));}byte[] methods=new byte[count];in.readFully(methods);boolean none=false;for(byte m:methods)if(m==1)none=true;if(!none)throw new IOException("VNC kimlik doğrulaması desteklenmiyor");out.writeByte(1);out.flush();if(in.readInt()!=0)throw new IOException("VNC kimlik doğrulaması reddedildi");out.writeByte(1);out.flush();width=in.readUnsignedShort();height=in.readUnsignedShort();byte[] serverFormat=new byte[16];in.readFully(serverFormat);int nameLength=in.readInt();readString(nameLength);if(width<1||height<1||width>4096||height>4096)throw new IOException("Geçersiz ekran boyutu");
 pixels=new int[width*height];synchronized(writeLock){out.writeByte(0);out.write(new byte[]{0,0,0});out.writeByte(32);out.writeByte(24);out.writeByte(0);out.writeByte(1);out.writeShort(255);out.writeShort(255);out.writeShort(255);out.writeByte(16);out.writeByte(8);out.writeByte(0);out.write(new byte[3]);out.writeByte(2);out.writeByte(0);out.writeShort(1);out.writeInt(0);out.flush();}
 boolean incremental=false;while(active){synchronized(writeLock){out.writeByte(3);out.writeByte(incremental?1:0);out.writeShort(0);out.writeShort(0);out.writeShort(width);out.writeShort(height);out.flush();}int type=in.readUnsignedByte();if(type==0){in.readUnsignedByte();int rects=in.readUnsignedShort();for(int i=0;i<rects;i++){int x=in.readUnsignedShort(),y=in.readUnsignedShort(),w=in.readUnsignedShort(),h=in.readUnsignedShort(),encoding=in.readInt();if(encoding!=0||x+w>width||y+h>height)throw new IOException("RFB kodlaması desteklenmiyor: "+encoding);for(int yy=y;yy<y+h;yy++)for(int xx=x;xx<x+w;xx++){int b=in.readUnsignedByte(),g=in.readUnsignedByte(),r=in.readUnsignedByte();in.readUnsignedByte();pixels[yy*width+xx]=Color.rgb(r,g,b);}}incremental=true;runOnUiThread(()->view.invalidate());}else if(type==2){}else if(type==3){in.read(new byte[3]);int len=in.readInt();readString(len);}else throw new IOException("Bilinmeyen RFB mesajı: "+type);}}
 catch(Exception e){if(active)runOnUiThread(()->new AlertDialog.Builder(this).setTitle("VNC bağlantısı").setMessage(e.getMessage()).setPositiveButton("Kapat",(d,w)->finish()).show());}}
 String readString(int n)throws IOException{if(n<0||n>1048576)throw new IOException("Geçersiz veri uzunluğu");byte[] a=new byte[n];in.readFully(a);return new String(a,"UTF-8");}
 void pointer(int x,int y,int mask){try{synchronized(writeLock){if(out==null)return;out.writeByte(5);out.writeByte(mask);out.writeShort(Math.max(0,Math.min(width-1,x)));out.writeShort(Math.max(0,Math.min(height-1,y)));out.flush();}}catch(Exception ignored){}}
 void key(int sym,boolean down){try{synchronized(writeLock){if(out==null)return;out.writeByte(4);out.writeByte(down?1:0);out.writeShort(0);out.writeInt(sym);out.flush();}}catch(Exception ignored){}}
 @Override public boolean onKeyDown(int code,KeyEvent e){if(code==KeyEvent.KEYCODE_BACK)return super.onKeyDown(code,e);int u=e.getUnicodeChar();int k=code==KeyEvent.KEYCODE_ENTER?0xff0d:code==KeyEvent.KEYCODE_DEL?0xff08:code==KeyEvent.KEYCODE_DPAD_LEFT?0xff51:code==KeyEvent.KEYCODE_DPAD_UP?0xff52:code==KeyEvent.KEYCODE_DPAD_RIGHT?0xff53:code==KeyEvent.KEYCODE_DPAD_DOWN?0xff54:u;if(k>0){key(k,true);return true;}return super.onKeyDown(code,e);}
 @Override public boolean onKeyUp(int code,KeyEvent e){int u=e.getUnicodeChar();int k=code==KeyEvent.KEYCODE_ENTER?0xff0d:code==KeyEvent.KEYCODE_DEL?0xff08:code==KeyEvent.KEYCODE_DPAD_LEFT?0xff51:code==KeyEvent.KEYCODE_DPAD_UP?0xff52:code==KeyEvent.KEYCODE_DPAD_RIGHT?0xff53:code==KeyEvent.KEYCODE_DPAD_DOWN?0xff54:u;if(k>0){key(k,false);return true;}return super.onKeyUp(code,e);}
 class Frame extends View {Paint p=new Paint(3);Frame(){super(VncActivity.this);setFocusable(true);requestFocus();} @Override protected void onDraw(Canvas c){super.onDraw(c);if(pixels==null){p.setColor(Color.WHITE);p.setTextSize(30);c.drawText("VM ekranına bağlanılıyor…",24,64,p);return;}Bitmap bitmap=Bitmap.createBitmap(pixels,width,height,Bitmap.Config.ARGB_8888);c.drawBitmap(bitmap,null,new Rect(0,0,getWidth(),getHeight()),p);bitmap.recycle();} @Override public boolean onTouchEvent(android.view.MotionEvent e){if(pixels==null)return true;int x=(int)(e.getX()*width/getWidth()),y=(int)(e.getY()*height/getHeight());int mask=e.getActionMasked()==MotionEvent.ACTION_UP?0:1;pointer(x,y,mask);return true;} @Override public boolean onGenericMotionEvent(MotionEvent e){if(pixels==null)return false;if((e.getSource()&InputDevice.SOURCE_MOUSE)==InputDevice.SOURCE_MOUSE){int x=(int)(e.getX()*width/getWidth()),y=(int)(e.getY()*height/getHeight());int mask=(e.getButtonState()&MotionEvent.BUTTON_PRIMARY)!=0?1:0;pointer(x,y,mask);return true;}return false;}}
 @Override protected void onDestroy(){active=false;try{if(socket!=null)socket.close();}catch(Exception ignored){}super.onDestroy();}
}
